package com.mealmate.order;import org.springframework.kafka.annotation.*;import org.springframework.stereotype.*;import java.util.*;@Component class OrderKafkaConsumer{final OrderRepository r;OrderKafkaConsumer(OrderRepository x){r=x;}@KafkaListener(topics={"payment-events","delivery-events"},groupId="delivery-order-saga")void on(OrderService.Event e){var o=r.findById(e.orderId()).orElse(null);if(o==null)return;if(e.type().equals("DeliveryAssigned"))o.setStatus(OrderStatus.CONFIRMED);if(e.type().equals("PaymentFailed")||e.type().equals("DeliveryAssignmentFailed"))o.setStatus(OrderStatus.CANCELLED);r.save(o);}}
